/**
 * tests/unit/institutional-decisions.test.ts — PR-05 + PR-06 + PR-07 exit
 * condition.
 *
 * "A consequential action produces a durable Decision record." and
 * "Escalation is generated by policy, not by frontend code."
 *
 * The DB-backed chain runs the full institutional loop: an authority
 * refusal generates an escalation (the case stays put); an approved
 * transition generates a durable decision that pins actor + role_context
 * + authority_source + the exact authority rule. A decision record is
 * the institutional decision history, not a PATCH status flip.
 */
import { describe, it, expect, beforeAll } from "vitest";
import { randomUUID } from "crypto";

const HAS_DB = !!process.env.DATABASE_URL;

describe("institutional decision loop (DB-backed)", () => {
  if (!HAS_DB) {
    it("skipped — no DATABASE_URL set", () => {
      expect(true).toBe(true);
    });
    return;
  }

  let principalId: string;
  let managerId: string;

  beforeAll(async () => {
    const { query } = await import("@/lib/postgres");
    principalId = randomUUID();
    managerId = randomUUID();
    await query(
      "INSERT INTO public.users (id, name, role) VALUES ($1,'test-principal','principal'),($2,'test-manager','hostel_manager') ON CONFLICT (id) DO NOTHING",
      [principalId, managerId],
    );
  });

  it("an authority refusal generates an escalation, not a state move", async () => {
    const { createCase } = await import("@/lib/institutional/cases");
    const { decideAndTransition } = await import("@/lib/institutional/decisions");
    const { getCase } = await import("@/lib/institutional/cases");

    const c = await createCase({
      type: "gate_pass",
      subjectType: "student",
      subjectId: "23JJ1A0599",
      origin: "decision-e2e",
      payload: { duration_days: 15 },
      actor: { id: managerId, role: "hostel_manager", roleContext: "administrative" },
    });

    // A 15-day request from a hostel_manager (bound is 3 days): refused →
    // escalation generated, the instance stays put, the case stays OPEN.
    const out = await decideAndTransition(
      c.id,
      "approve",
      { id: managerId, role: "hostel_manager", roleContext: "administrative" },
      "gate_pass",
      { durationDays: 15 },
      "15-day gate pass",
    );
    expect(out.escalated).toBe(true);
    expect(out.escalationId).toMatch(/^[0-9a-f-]{36}$/i);
    expect(out.decision).toBeNull();

    // The escalation row exists, carries an explicit reason (not just
    // "new request"), and targets a higher authority.
    const { query } = await import("@/lib/postgres");
    const { rows } = await query<{ reason: string; target_role: string | null; status: string }>(
      `SELECT reason, target_role, status FROM public.escalations WHERE id = $1`,
      [out.escalationId],
    );
    expect(rows.length).toBe(1);
    expect(rows[0].reason).toBe("AUTHORITY_INSUFFICIENT");
    expect(rows[0].status).toBe("OPEN");

    // The case did NOT move: it is still in its lifecycle, not approved.
    const c2 = await getCase(c.id);
    expect(c2!.state).not.toBe("CLOSED");
  });

  it("an approved transition produces a durable Decision record", async () => {
    const { createCase } = await import("@/lib/institutional/cases");
    const { decideAndTransition, toDecisionRecord } = await import("@/lib/institutional/decisions");

    const c = await createCase({
      type: "gate_pass",
      subjectType: "student",
      subjectId: "23JJ1A0599",
      origin: "decision-e2e-approve",
      payload: { duration_days: 15 },
      actor: { id: principalId, role: "principal", roleContext: "administrative" },
    });

    // The principal (no duration bound) approves the same 15-day request:
    // the case moves to 'approved' and a decision record is produced.
    const out = await decideAndTransition(
      c.id,
      "approve",
      { id: principalId, role: "principal", roleContext: "chief_warden" },
      "gate_pass",
      { durationDays: 15 },
      "Verified emergency departure",
      [{ system: "gate", effect: "pass generated" }],
    );
    expect(out.escalated).toBe(false);
    expect(out.decision).not.toBeNull();

    // The decision record pins the full provenance (PR-11 audit invariant).
    const rec = toDecisionRecord(out.decision!);
    expect(rec.decisionId).toMatch(/^DEC-\d{4}-\d{4}$/);
    expect(rec.caseId).toBe(c.id);
    expect(rec.actorId).toBe(principalId);
    expect(rec.actorRole).toBe("principal");
    expect(rec.roleContext).toBe("chief_warden");
    expect(rec.authoritySource).toBe("role");
    expect(rec.decision).toBe("approve");
    expect(rec.correlationId).toBe(rec.decisionId);

    // The decision is durable in the ledger, not just in memory.
    const { query } = await import("@/lib/postgres");
    const { rows } = await query<{ decision_no: string; operation: string }>(
      `SELECT decision_no, operation FROM public.decisions WHERE case_id = $1`,
      [c.id],
    );
    expect(rows.length).toBe(1);
    expect(rows[0].operation).toBe("approve");
    expect(rows[0].decision_no).toBe(rec.decisionId);
  });

  it("a decision via delegation cites the grant, not the direct role", async () => {
    const { query } = await import("@/lib/postgres");
    const { createCase } = await import("@/lib/institutional/cases");
    const { recordDecision, toDecisionRecord } = await import("@/lib/institutional/decisions");
    const { authorize } = await import("@/lib/institutional/workflow");

    // A vice_principal holds a live delegation to act as principal on
    // gate_pass approvals. The decision must cite the delegation, not
    // the vice_principal role (which has no direct policy).
    const vpId = randomUUID();
    await query(
      "INSERT INTO public.users (id, name, role) VALUES ($1,'test-vp','vice_principal') ON CONFLICT (id) DO NOTHING",
      [vpId],
    );
    await query(
      `INSERT INTO public.delegations
         (id, delegator_id, delegatee_id, role, scope_entity, can_mutate,
          starts_at, expires_at, requires_approval, approved_by, note)
       VALUES
         (gen_random_uuid(), $1, $2, 'principal', NULL, TRUE,
          now() - interval '1 hour', now() + interval '1 day',
          FALSE, $1, 'test delegation for decision engine')`,
      [principalId, vpId],
    );

    const c = await createCase({
      type: "gate_pass",
      subjectType: "student",
      subjectId: "23JJ1A0599",
      origin: "decision-delegation",
      payload: { duration_days: 15 },
      actor: { id: vpId, role: "vice_principal", roleContext: "administrative" },
    });

    // The VP's direct role has no gate_pass.approve policy, but the
    // delegation does: authorize() must satisfy it via the grant.
    const auth = await authorize({
      actorId: vpId,
      role: "vice_principal",
      context: "administrative",
      operation: "approve",
      caseType: "gate_pass",
      scope: "institution",
      authoritySource: "delegation",
    });
    expect(auth.allowed, "delegation should satisfy the principal policy").toBe(true);

    const d = await recordDecision({
      caseId: c.id,
      operation: "approve",
      actor: { id: vpId, role: "vice_principal", roleContext: "administrative" },
      authority: auth,
      reason: "Acting under delegation",
    });
    const rec = toDecisionRecord(d);
    expect(rec.authoritySource, "a delegation-satisfied decision is marked as such").toBe("delegation");
  });
});
